CREATE TABLE `book` (
  `isbn` char(13) NOT NULL COMMENT 'ISBN-13',
  `title` varchar(200) NOT NULL COMMENT '서명',
  `publisher_id` int unsigned NOT NULL COMMENT '출판사번호',
  `category_code` char(3) NOT NULL COMMENT '분류코드 (KDC 주류)',
  `kdc_no` varchar(20) DEFAULT NULL COMMENT 'KDC 분류기호 (예: 813.7)',
  `pub_year` smallint unsigned DEFAULT NULL COMMENT '발행연도',
  `price` int unsigned DEFAULT NULL COMMENT '정가(원)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '등록일시',
  PRIMARY KEY (`isbn`),
  KEY `fk_book_publisher` (`publisher_id`),
  KEY `fk_book_category` (`category_code`),
  KEY `idx_book_title` (`title`),
  CONSTRAINT `fk_book_category` FOREIGN KEY (`category_code`) REFERENCES `category` (`category_code`) ON UPDATE CASCADE,
  CONSTRAINT `fk_book_publisher` FOREIGN KEY (`publisher_id`) REFERENCES `publisher` (`publisher_id`) ON UPDATE CASCADE,
  CONSTRAINT `ck_book_isbn` CHECK (regexp_like(`isbn`,_utf8mb4'^97[89][0-9]{10}$')),
  CONSTRAINT `ck_book_pub_year` CHECK ((`pub_year` between 1450 and 2100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='도서';
