DROP TABLE IF EXISTS `book_copy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `book_copy` (
  `copy_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '복본번호',
  `reg_no` varchar(10) NOT NULL COMMENT '등록번호 (바코드)',
  `isbn` char(13) NOT NULL COMMENT 'ISBN',
  `call_no` varchar(40) NOT NULL COMMENT '청구기호',
  `location` varchar(30) NOT NULL DEFAULT '종합자료실' COMMENT '배가위치',
  `status` varchar(10) NOT NULL DEFAULT '대출가능' COMMENT '복본상태',
  `acquired_date` date NOT NULL DEFAULT (curdate()) COMMENT '입수일',
  `removed_date` date DEFAULT NULL COMMENT '분실·폐기 처리일',
  PRIMARY KEY (`copy_id`),
  UNIQUE KEY `uq_book_copy_reg_no` (`reg_no`),
  KEY `idx_book_copy_isbn_status` (`isbn`,`status`),
  CONSTRAINT `fk_book_copy_book` FOREIGN KEY (`isbn`) REFERENCES `book` (`isbn`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_book_copy_reg_no` CHECK (regexp_like(`reg_no`,_utf8mb4'^EM[0-9]{6}$')),
  CONSTRAINT `ck_book_copy_removed` CHECK (((`status` in (_utf8mb4'분실',_utf8mb4'폐기')) = (`removed_date` is not null))),
  CONSTRAINT `ck_book_copy_status` CHECK ((`status` in (_utf8mb4'대출가능',_utf8mb4'대출중',_utf8mb4'분실',_utf8mb4'폐기')))
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='도서복본';
/*!40101 SET character_set_client = @saved_cs_client */;

