CREATE TABLE `fine` (
  `fine_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '연체료번호',
  `loan_id` int unsigned NOT NULL COMMENT '대출번호',
  `overdue_days` smallint unsigned NOT NULL COMMENT '연체일수 (휴관일 제외)',
  `amount` int unsigned NOT NULL COMMENT '연체료(원) - 부과 시점 정책으로 확정',
  `status` varchar(10) NOT NULL DEFAULT '미납' COMMENT '납부상태',
  `imposed_date` date NOT NULL DEFAULT (curdate()) COMMENT '부과일',
  `paid_date` date DEFAULT NULL COMMENT '처리일 (납부/면제)',
  `staff_id` int unsigned DEFAULT NULL COMMENT '납부·면제 처리 사서',
  PRIMARY KEY (`fine_id`),
  UNIQUE KEY `uq_fine_loan` (`loan_id`),
  KEY `fk_fine_staff` (`staff_id`),
  KEY `idx_fine_status` (`status`),
  CONSTRAINT `fk_fine_loan` FOREIGN KEY (`loan_id`) REFERENCES `loan` (`loan_id`),
  CONSTRAINT `fk_fine_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `ck_fine_days` CHECK ((`overdue_days` > 0)),
  CONSTRAINT `ck_fine_paid` CHECK (((`status` = _utf8mb4'미납') = (`paid_date` is null))),
  CONSTRAINT `ck_fine_status` CHECK ((`status` in (_utf8mb4'미납',_utf8mb4'납부',_utf8mb4'면제')))
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='연체료';
