-- Table structure for table `loan`
--

DROP TABLE IF EXISTS `loan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `loan` (
  `loan_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '대출번호',
  `copy_id` int unsigned NOT NULL COMMENT '복본번호',
  `member_id` int unsigned NOT NULL COMMENT '회원번호',
  `staff_id` int unsigned NOT NULL COMMENT '대출 처리 사서',
  `loan_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '대출일시',
  `due_date` date NOT NULL COMMENT '반납예정일 (연장 시 갱신)',
  `return_date` datetime DEFAULT NULL COMMENT '반납일시',
  `return_type` varchar(10) DEFAULT NULL COMMENT '반납구분 (반납/분실)',
  `return_staff_id` int unsigned DEFAULT NULL COMMENT '반납 처리 사서',
  `active_copy_id` int unsigned GENERATED ALWAYS AS (if((`return_date` is null),`copy_id`,NULL)) STORED COMMENT '미반납 복본 (생성 컬럼)',
  PRIMARY KEY (`loan_id`),
  UNIQUE KEY `uq_loan_active_copy` (`active_copy_id`),
  KEY `fk_loan_copy` (`copy_id`),
  KEY `fk_loan_staff` (`staff_id`),
  KEY `fk_loan_return_staff` (`return_staff_id`),
  KEY `idx_loan_member_return` (`member_id`,`return_date`),
  KEY `idx_loan_due_date` (`due_date`),
  KEY `idx_loan_loan_date` (`loan_date`),
  CONSTRAINT `fk_loan_copy` FOREIGN KEY (`copy_id`) REFERENCES `book_copy` (`copy_id`),
  CONSTRAINT `fk_loan_member` FOREIGN KEY (`member_id`) REFERENCES `member` (`member_id`),
  CONSTRAINT `fk_loan_return_staff` FOREIGN KEY (`return_staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_loan_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `ck_loan_due_date` CHECK ((`due_date` >= cast(`loan_date` as date))),
  CONSTRAINT `ck_loan_return_date` CHECK (((`return_date` is null) or (`return_date` >= `loan_date`))),
  CONSTRAINT `ck_loan_return_type` CHECK ((`return_type` in (_utf8mb4'반납',_utf8mb4'분실'))),
  CONSTRAINT `ck_loan_returned` CHECK ((((`return_date` is null) = (`return_type` is null)) and ((`return_date` is null) = (`return_staff_id` is null))))
) ENGINE=InnoDB AUTO_INCREMENT=231 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='대출';
/*!40101 SET character_set_client = @saved_cs_client */;

