--
-- Table structure for table `member`
--

DROP TABLE IF EXISTS `member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member` (
  `member_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '회원번호 (내부 식별자)',
  `member_no` varchar(20) NOT NULL COMMENT '학번·교번 (로그인 ID)',
  `password_hash` varchar(255) NOT NULL COMMENT '비밀번호 해시',
  `name` varchar(30) NOT NULL COMMENT '이름',
  `type_code` varchar(10) NOT NULL COMMENT '회원구분코드',
  `department` varchar(50) DEFAULT NULL COMMENT '소속 (학과·부서)',
  `phone` varchar(13) NOT NULL COMMENT '휴대전화 (010-0000-0000)',
  `email` varchar(100) DEFAULT NULL COMMENT '이메일',
  `status` varchar(10) NOT NULL DEFAULT '정상' COMMENT '계정상태',
  `join_date` date NOT NULL DEFAULT (curdate()) COMMENT '가입일',
  `withdraw_date` date DEFAULT NULL COMMENT '탈퇴일',
  PRIMARY KEY (`member_id`),
  UNIQUE KEY `uq_member_no` (`member_no`),
  UNIQUE KEY `uq_member_phone` (`phone`),
  UNIQUE KEY `uq_member_email` (`email`),
  KEY `fk_member_type` (`type_code`),
  KEY `idx_member_name` (`name`),
  CONSTRAINT `fk_member_type` FOREIGN KEY (`type_code`) REFERENCES `member_type` (`type_code`) ON UPDATE CASCADE,
  CONSTRAINT `ck_member_no` CHECK (regexp_like(`member_no`,_utf8mb4'^[0-9A-Za-z]{4,20}$')),
  CONSTRAINT `ck_member_phone` CHECK (regexp_like(`phone`,_utf8mb4'^01[0-9]-[0-9]{3,4}-[0-9]{4}$')),
  CONSTRAINT `ck_member_status` CHECK ((`status` in (_utf8mb4'정상',_utf8mb4'탈퇴'))),
  CONSTRAINT `ck_member_withdraw` CHECK (((`status` = _utf8mb4'탈퇴') = (`withdraw_date` is not null)))
) ENGINE=InnoDB AUTO_INCREMENT=10028 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='회원';
/*!40101 SET character_set_client = @saved_cs_client */;

